<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><title>{{ $quotation->quotation_no }}</title><link rel="stylesheet" href="{{ public_path('assets/css/receipt.css') }}"></head><body><div class="receipt-header"><h1>{{ $quotation->party_snapshot['business']['name'] }}</h1><p>{{ $quotation->party_snapshot['business']['address'] }}</p><p>GSTIN: {{ $quotation->party_snapshot['business']['gst_number'] }}</p></div><table class="receipt-meta"><tr><td><h2>{{ __('Quotation') }} {{ $quotation->quotation_no }}</h2><p>{{ __('Date') }}: {{ $quotation->quotation_date }}</p><p>{{ __('Valid until') }}: {{ $quotation->valid_until }}</p><p>{{ __('Status') }}: {{ __(ucfirst($quotation->status)) }}</p></td><td><h2>{{ $quotation->party_snapshot['customer']['name'] }}</h2><p>{{ $quotation->party_snapshot['customer']['address'] }}</p></td></tr></table><table class="receipt-lines"><thead><tr><th>{{ __('Item') }}</th><th>{{ __('Qty / unit') }}</th><th class="money">{{ __('Rate') }}</th><th class="money">GST</th><th class="money">{{ __('Line total') }}</th></tr></thead><tbody>@foreach($quotation->items as $line)<tr><td>{{ $line->item_name }}</td><td>{{ $line->qty }} {{ $line->unit }}</td><td class="money">{{ number_format($line->rate,2) }}</td><td class="money">{{ number_format($line->cgst_amount+$line->sgst_amount,2) }}</td><td class="money">{{ number_format($line->line_total,2) }}</td></tr>@endforeach</tbody></table><div class="receipt-summary"><table class="receipt-meta">@foreach(['taxable_amount'=>__('Taxable amount'),'discount'=>__('Discount'),'cgst_total'=>'CGST','sgst_total'=>'SGST','round_off'=>__('Round off'),'grand_total'=>__('Quotation total')] as $key=>$label)<tr><td>{{ $label }}</td><td class="money">INR {{ number_format($quotation->totals[$key],2) }}</td></tr>@endforeach</table><p>{{ $quotation->notes }}</p><p class="receipt-note">{{ __('This is a quotation, not a tax invoice or payment receipt.') }}</p></div></body></html>
